node -e "
global.window = global;
const fs = require('fs');
const html = fs.readFileSync('index.html','utf8');
const m = html.match(/<script>([\s\S]*)<\/script>/);
const ctxStub = new Proxy({}, { get: (t,p) => (p==='canvas'?{}:()=>{}) });
global.document = { getElementById: () => ({ getContext: () => ctxStub, width:800, height:800 }) };
global.requestAnimationFrame = () => {};
eval(m[1]);

function inPoly(x, y, angle) {
  const N=9, R=260, CX=400, CY=400;
  for (let i=0;i<N;i++){
    const a1 = angle + i/N*2*Math.PI, a2 = angle + (i+1)/N*2*Math.PI;
    const ax=CX+R*Math.cos(a1), ay=CY+R*Math.sin(a1);
    const bx=CX+R*Math.cos(a2), by=CY+R*Math.sin(a2);
    const ex=bx-ax, ey=by-ay, len=Math.hypot(ex,ey);
    let nx=ey/len, ny=-ex/len;
    let d=(x-ax)*nx+(y-ay)*ny;
    let dc=(CX-ax)*nx+(CY-ay)*ny;
    if (dc<0){nx=-nx;ny=-ny;d=-d;}
    if (d < 14 - 1e-6) return false;
  }
  return true;
}
let allOk = true;
for (let s=1; s<=20; s++) {
  window.__bench.step(0.5);
  const st = window.__bench.getState();
  for (const b of st.balls) {
    if (!inPoly(b.x, b.y, st.poly.angle)) { allOk=false; console.log('OUT of poly at t=',st.t, b); }
  }
  for (let i=0;i<st.balls.length;i++) for (let j=i+1;j<st.balls.length;j++){
    const a=st.balls[i], c=st.balls[j];
    if (Math.hypot(a.x-c.x,a.y-c.y) < 28 - 1e-6) { allOk=false; console.log('OVERLAP', a.id, c.id, Math.hypot(a.x-c.x,a.y-c.y)); }
  }
}
console.log('all inside polygon & no overlap over 10s:', allOk);
// determinism check
eval(m[1]); // re-init? no, makeBalls only on load. Instead check velocities sane
const st = window.__bench.getState();
const maxV = Math.max(...st.balls.map(b=>Math.hypot(b.vx,b.vy)));
console.log('max speed after 10s:', maxV.toFixed(1));
"

