input.oldString:
function closestOnSegment(px, py, ax, ay, bx, by) {
  var abx = bx - ax;
  var aby = by - ay;
  var apx = px - ax;
  var apy = py - ay;
  var len2 = abx * abx + aby * aby;
  var t = len2 > 0 ? (apx * abx + apy * aby) / len2 : 0;
  if (t < 0) t = 0;
  if (t > 1) t = 1;
  return { x: ax + abx * t, y: ay + aby * t };
}

function resolveWalls() {
  var vs = vertices(polyAngle());
  for (var b = 0; b < balls.length; b++) {
    var ball = balls[b];
    var bestD2 = Infinity;
    var bestPx = 0;
    var bestPy = 0;
    for (var i = 0; i < CFG.N; i++) {
      var a = vs[i];
      var c = vs[(i + 1) % CFG.N];
      var p = closestOnSegment(ball.x, ball.y, a.x, a.y, c.x, c.y);
      var dx = ball.x - p.x;
      var dy = ball.y - p.y;
      var d2 = dx * dx + dy * dy;
      if (d2 < bestD2) { bestD2 = d2; bestPx = p.x; bestPy = p.y; }
    }
    var dist = Math.sqrt(bestD2);
    if (dist < ball.r) {
      var nx, ny;
      if (dist > 1e-9) {
        nx = (ball.x - bestPx) / dist;
        ny = (ball.y - bestPy) / dist;
      } else {
        nx = (ball.x - CFG.CX);
        ny = (ball.y - CFG.CY);
        var nl = Math.sqrt(nx * nx + ny * ny) || 1;
        nx /= nl; ny /= nl;
      }
      ball.x = bestPx + nx * ball.r;
      ball.y = bestPy + ny * ball.r;
      var wv = wallVelocity(bestPx, bestPy);
      var rvx = ball.vx - wv.x;
      var rvy = ball.vy - wv.y;
      var vn = rvx * nx + rvy * ny;
      if (vn < 0) {
        var tx = -ny;
        var ty = nx;
        var vt = rvx * tx + rvy * ty;
        var vn2 = -CFG.REST * vn;
        var vt2 = vt * (1 - CFG.FRICTION);
        ball.vx = wv.x + nx * vn2 + tx * vt2;
        ball.vy = wv.y + ny * vn2 + ty * vt2;
        ball.angVel = 0.5 * ball.angVel + 0.5 * (vt2 / ball.r);
      }
    }
  }
}

input.newString:
function edgeData(vs, i) {
  var a = vs[i];
  var c = vs[(i + 1) % CFG.N];
  var ex = c.x - a.x;
  var ey = c.y - a.y;
  var len = Math.sqrt(ex * ex + ey * ey);
  var nx = ey / len;
  var ny = -ex / len;
  var dc = (CFG.CX - a.x) * nx + (CFG.CY - a.y) * ny;
  if (dc < 0) { nx = -nx; ny = -ny; }
  return { nx: nx, ny: ny, ax: a.x, ay: a.y };
}

function resolveWalls() {
  var vs = vertices(polyAngle());
  var edges = [];
  for (var i = 0; i < CFG.N; i++) edges.push(edgeData(vs, i));
  for (var b = 0; b < balls.length; b++) {
    var ball = balls[b];
    var contact = null;
    for (var it = 0; it < 40; it++) {
      var anyPen = false;
      var worst = null;
      var worstPen = 0;
      for (var i = 0; i < edges.length; i++) {
        var e = edges[i];
        var d = (ball.x - e.ax) * e.nx + (ball.y - e.ay) * e.ny;
        var pen = ball.r - d;
        if (pen > 0) {
          anyPen = true;
          ball.x += e.nx * pen;
          ball.y += e.ny * pen;
          if (pen > worstPen) { worstPen = pen; worst = e; }
        }
      }
      if (!anyPen) break;
      if (worst) contact = worst;
    }
    if (contact) {
      var e = contact;
      var cxp = ball.x - e.nx * ball.r;
      var cyp = ball.y - e.ny * ball.r;
      var wv = wallVelocity(cxp, cyp);
      var rvx = ball.vx - wv.x;
      var rvy = ball.vy - wv.y;
      var vn = rvx * e.nx + rvy * e.ny;
      if (vn < 0) {
        var tx = -e.ny;
        var ty = e.nx;
        var vt = rvx * tx + rvy * ty;
        var vn2 = -CFG.REST * vn;
        var vt2 = vt * (1 - CFG.FRICTION);
        ball.vx = wv.x + e.nx * vn2 + tx * vt2;
        ball.vy = wv.y + e.ny * vn2 + ty * vt2;
        ball.angVel = 0.5 * ball.angVel + 0.5 * (vt2 / ball.r);
      }
    }
  }
}

